const {writeFile, copyFile, access} = require('fs').promises;
const {constants} = require('fs');
const path = require('path');

async function exists(path) {
    try {
        await access(path);
        return true;
    } catch {
        return false;
    }
}

const initCmd = [
    `init [preset] [devoir]`,
    'Créer des fichiers de scripts pour faciliter la correction.',
    (y) => {
        y.option('preset', {
            type: 'string',
            describe: 'Le preset à utiliser pour ce fichier de facilitation. Le nom du devoir est assumé étant le même que le nom du preset.',
        }).option('d', {
            alias: 'devoir',
            type: 'string',
            describe: 'Le nom du devoir pour le preset Devoirs. Un preset sera créé avec le même nom que le devoir.',
        });
    },
    async (args) => {
        let {preset} = args;
        let pt = '';
        if (!!preset) {
            let p = require('../presets.js').getPreset(preset);
            if (!p) {
                require('../../logger.js').warn(`Le preset ${preset} n'existe pas`);
            }
            pt = '--preset ' + preset;
            args.devoir = preset;
        } else {
            if (!args.devoir) {
                console.log("Le nom du devoir doit être fourni (-d=devoir)");
                return;
            }
            preset = args.devoir;
            let data = require('../assets/presets').devoirs(args.devoir);
            require('../presets.js').putPreset(preset, data);
            pt = '--preset ' + preset;
        }

        let files = [];
        switch (process.platform) {
            case 'win32':
                files = require('../assets/win32.js').files;
                break;
            case 'darwin':
                require('../../logger.js').error("MacOS n'est pas supporté pour cette fonctionnalité pour l'instant");
                return;
            case 'linux':
                files = require('../assets/linux.js').files;
                break;
            default:
                require('../../logger.js').error(
                    `${process.platform} n'est pas supporté pour cette fonctionnalité`
                );
                return;
        }
        try {
            const promises = files.map(async (file) => {
                let {name, content, postProcess} = file;
                name = name.replace('@{preset}', preset);
                content = content
                    .replace(/@{preset}/g, preset)
                    .replace(/@{curdir}/g, process.cwd());
                await writeFile(name, content);
                if (postProcess) return postProcess(name);
            });
            promises.push((async () => {
                const filename = path.join(process.cwd(), `commentaires-${args.devoir}.txt`);
                if (!(await exists(filename))) {
                    return copyFile(path.join(__dirname, '..', 'assets', 'commentaires.txt'), filename);
                }
                return Promise.resolve();
            })());
            await Promise.all(promises);
        } catch (e) {
            require('../../logger.js').trace(e);
        }
    },
];

module.exports = initCmd;

